wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(25491398294485651630)
,p_chart_id=>wwv_flow_imp.id(25491395984993651628)
,p_seq=>10
,p_name=>'2016 spend'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH customer_orders AS (',
'    SELECT',
'        c.customer_id,',
'        c.name AS customer_name,',
'        SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2016 THEN oi.quantity * oi.unit_price ELSE 0 END) AS spend_2016,',
'        SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2017 THEN oi.quantity * oi.unit_price ELSE 0 END) AS spend_2017,',
'        COUNT(DISTINCT CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2016 THEN o.order_id END) AS orders_2016,',
'        COUNT(DISTINCT CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2017 THEN o.order_id END) AS orders_2017',
'    FROM',
'        customers c',
'        JOIN orders o ON c.customer_id = o.customer_id',
'        JOIN order_items oi ON o.order_id = oi.order_id',
'    WHERE',
'        o.status = ''Shipped''',
'        AND EXTRACT(YEAR FROM o.order_date) IN (2016, 2017)',
'    GROUP BY',
'        c.customer_id, c.name',
'),',
'customer_stats AS (',
'    SELECT',
'        customer_id,',
'        customer_name,',
'        spend_2016,',
'        spend_2017,',
'        orders_2016,',
'        orders_2017,',
'        ROUND((spend_2017 - spend_2016) / NULLIF(spend_2016, 0) * 100, 1) AS growth_percentage,',
'        ROUND(spend_2016 / NULLIF(orders_2016, 0), 2) AS avg_order_2016,',
'        ROUND(spend_2017 / NULLIF(orders_2017, 0), 2) AS avg_order_2017',
'    FROM',
'        customer_orders',
')',
'SELECT',
'    customer_name AS "Customer Name",',
'    ROUND(spend_2016, 2) AS "2016 Spend",',
'    ROUND(spend_2017, 2) AS "2017 Spend",',
'    (spend_2017 - spend_2016) AS "Spend Difference",',
'    growth_percentage AS "Growth %",',
'    orders_2016 AS "2016 Orders",',
'    orders_2017 AS "2017 Orders",',
'    avg_order_2016 AS "2016 Avg Order",',
'    avg_order_2017 AS "2017 Avg Order",',
'    CASE',
'        WHEN spend_2016 = 0 THEN ''New Customer''',
'        WHEN growth_percentage > 50 THEN ''Rapid Growth''',
'        WHEN growth_percentage > 20 THEN ''Steady Growth''',
'        WHEN growth_percentage < -20 THEN ''Declining''',
'        ELSE ''Stable''',
'    END AS "Trend Category"',
'FROM',
'    customer_stats',
'WHERE',
'    spend_2016 > 0 ',
'    AND spend_2017 > 0',
'    AND orders_2016 >= 1',
'    AND orders_2017 >= 1',
'ORDER BY',
'    ABS(growth_percentage) DESC',
'FETCH FIRST 20 ROWS ONLY'))
,p_series_type=>'bar'
,p_items_value_column_name=>'2016 Spend'
,p_items_label_column_name=>'Customer Name'
,p_line_style=>'solid'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>false
);
