'        WHEN spend_2016 = 0 THEN ''New Customer''',
'        WHEN growth_percentage > 50 THEN ''Rapid Growth''',
'        WHEN growth_percentage > 20 THEN ''Steady Growth''',
'        WHEN growth_percentage < -20 THEN ''Declining''',
'        ELSE ''Stable''',
'    END AS "Trend Category"',
'FROM',
'    customer_stats',
'WHERE',
'    spend_2016 > 0 ',
'    AND spend_2017 > 0',
'    AND orders_2016 >= 1',
'    AND orders_2017 >= 1',
'ORDER BY',
'    ABS(growth_percentage) DESC',
'FETCH FIRST 20 ROWS ONLY'))
,p_series_type=>'lineWithArea'
,p_items_value_column_name=>'Growth %'
,p_items_label_column_name=>'Customer Name'
,p_line_style=>'solid'
,p_line_type=>'auto'
,p_marker_rendered=>'auto'
,p_marker_shape=>'auto'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>false
);
