wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(24677641828068737728)
,p_plug_name=>'Sales Performance comparison'
,p_title=>'Previous vs current year sales'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    TO_CHAR(o.order_date, ''Month'') AS month,',
'    SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2016 THEN oi.quantity * oi.unit_price ELSE 0 END) AS sales_2016,',
'    SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2017 THEN oi.quantity * oi.unit_price ELSE 0 END) AS sales_2017,',
'    ROUND(',
'        (SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2017 THEN oi.quantity * oi.unit_price ELSE 0 END) - ',
'         SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2016 THEN oi.quantity * oi.unit_price ELSE 0 END)) /',
'        NULLIF(SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2016 THEN oi.quantity * oi.unit_price ELSE 0 END), 0) * 100, ',
'        2',
'    ) AS growth_percentage',
'FROM ',
'    orders o',
'JOIN ',
'    order_items oi ON o.order_id = oi.order_id',
'WHERE ',
'    EXTRACT(YEAR FROM o.order_date) IN (2016, 2017)',
'    AND o.status = ''Shipped''',
'GROUP BY ',
'    TO_CHAR(o.order_date, ''Month''),',
'    EXTRACT(MONTH FROM o.order_date)',
'ORDER BY ',
'    EXTRACT(MONTH FROM o.order_date)'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
