wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(25433659676589622712)
,p_chart_id=>wwv_flow_imp.id(25433659536847622711)
,p_seq=>10
,p_name=>'Top 10 Products by Revenue Growth (2016-2017)'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH product_sales AS (',
'    SELECT ',
'        p.product_id,',
'        p.product_name,',
'        pc.category_name,',
'        SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2016 THEN oi.quantity ELSE 0 END) AS qty_2016,',
'        SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2016 THEN oi.quantity * oi.unit_price ELSE 0 END) AS revenue_2016,',
'        SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2017 THEN oi.quantity ELSE 0 END) AS qty_2017,',
'        SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2017 THEN oi.quantity * oi.unit_price ELSE 0 END) AS revenue_2017',
'    FROM ',
'        products p',
'        JOIN order_items oi ON p.product_id = oi.product_id',
'        JOIN orders o ON oi.order_id = o.order_id',
'        JOIN product_categories pc ON p.category_id = pc.category_id',
'    WHERE ',
'        EXTRACT(YEAR FROM o.order_date) IN (2016, 2017)',
'        AND o.status = ''Shipped''',
'    GROUP BY ',
'        p.product_id, p.product_name, pc.category_name',
'),',
'product_performance AS (',
'    SELECT ',
'        product_id,',
'        product_name,',
'        category_name,',
'        qty_2016,',
'        qty_2017,',
'        revenue_2016,',
'        revenue_2017,',
'        qty_2017 - qty_2016 AS qty_change,',
'        revenue_2017 - revenue_2016 AS revenue_change,',
'        ROUND(',
'            CASE WHEN qty_2016 > 0 ',
'                 THEN (qty_2017 - qty_2016) / qty_2016 * 100 ',
'                 ELSE NULL ',
'            END, 2) AS qty_change_percent,',
'        ROUND(',
'            CASE WHEN revenue_2016 > 0 ',
'                 THEN (revenue_2017 - revenue_2016) / revenue_2016 * 100 ',
'                 ELSE NULL ',
'            END, 2) AS revenue_change_percent',
'    FROM ',
'        product_sales',
')',
'SELECT ',
'    product_name,',
'    revenue_change_percent,',
'    category_name,',
'    revenue_2016 AS "2016 Revenue",',
'    revenue_2017 AS "2017 Revenue",',
'    revenue_change AS "Revenue Change"',
'FROM ',
'    product_performance',
'WHERE ',
'    revenue_change_percent > 0',
'    AND revenue_2016 > 0  -- Ensure we only compare products that existed in both years',
'ORDER BY ',
'    revenue_change_percent DESC',
'FETCH FIRST 10 ROWS ONLY'))
,p_items_value_column_name=>'REVENUE_CHANGE_PERCENT'
,p_items_label_column_name=>'PRODUCT_NAME'
,p_color=>'#377d38'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>false
);
