'    JOIN orders o ON oi.order_id = o.order_id',
'WHERE',
'    o.status = ''Shipped''',
'    AND pc.category_name = ''CPU''',
'    AND EXTRACT(YEAR FROM o.order_date) = 2016',
'',
'UNION ALL',
'',
'SELECT',
'    ''2017'' AS year,',
'    SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2017 THEN oi.quantity * oi.unit_price ELSE 0 END) AS revenue,',
'    SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2017 THEN oi.quantity ELSE 0 END) AS units_sold',
'FROM',
'    product_categories pc',
'    JOIN products p ON pc.category_id = p.category_id',
'    JOIN order_items oi ON p.product_id = oi.product_id',
'    JOIN orders o ON oi.order_id = o.order_id',
'WHERE',
'    o.status = ''Shipped''',
'    AND pc.category_name = ''CPU''',
'    AND EXTRACT(YEAR FROM o.order_date) = 2017',
'ORDER BY year;'))
,p_items_value_column_name=>'REVENUE'
,p_items_label_column_name=>'YEAR'
,p_items_label_rendered=>true
,p_items_label_position=>'auto'
,p_items_label_display_as=>'VALUE'
);
end;
/
