wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(25458425992679671803)
,p_chart_id=>wwv_flow_imp.id(25458425822198671802)
,p_seq=>10
,p_name=>'Customer RFM Analysis (2017)'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH customer_stats AS (',
'    SELECT',
'        c.customer_id,',
'        c.name AS customer_name,',
'        c.credit_limit,',
'        c.website,',
'        COUNT(DISTINCT o.order_id) AS total_orders,',
'        SUM(oi.quantity * oi.unit_price) AS total_spend,',
'        MIN(o.order_date) AS first_order_date,',
'        MAX(o.order_date) AS last_order_date,',
'        -- 2017 activity (current year)',
'        COUNT(DISTINCT CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2017 THEN o.order_id END) AS orders_2017,',
'        SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2017 THEN oi.quantity * oi.unit_price ELSE 0 END) AS spend_2017,',
'        -- 2016 activity (prior year)',
'        COUNT(DISTINCT CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2016 THEN o.order_id END) AS orders_2016,',
'        SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2016 THEN oi.quantity * oi.unit_price ELSE 0 END) AS spend_2016,',
'        -- Averages',
'        AVG(oi.quantity * oi.unit_price) AS avg_order_value,',
'        -- Recency calculation (days since last order as of end of 2017)',
'        TO_DATE(''31-DEC-2017'', ''DD-MON-YYYY'') - MAX(o.order_date) AS days_since_last_order',
'    FROM',
'        customers c',
'        JOIN orders o ON c.customer_id = o.customer_id',
'        JOIN order_items oi ON o.order_id = oi.order_id',
'    WHERE',
'        o.status = ''Shipped''',
'        AND EXTRACT(YEAR FROM o.order_date) IN (2016, 2017)',
'    GROUP BY',
'        c.customer_id, c.name, c.credit_limit, c.website',
'),',
'customer_segmentation AS (',
'    SELECT',
'        customer_id,',
'        customer_name,',
'        credit_limit,',
'        website,',
'        total_orders,',
'        total_spend,',
'        ROUND(total_spend / NULLIF(total_orders, 0), 2) AS avg_order_value,',
'        orders_2016,',
'        spend_2016,',
'        orders_2017,',
'        spend_2017,',
'        ROUND((spend_2017 - spend_2016) / NULLIF(spend_2016, 0) * 100, 1) AS spend_growth_pct,',
'        first_order_date,',
'        last_order_date,',
'        days_since_last_order,',
'        CASE',
'            WHEN orders_2017 >= 5 AND spend_2017 >= 5000 THEN ''VIP''',
'            WHEN orders_2017 >= 3 AND spend_2017 >= 2000 THEN ''Frequent Buyer''',
'            WHEN spend_2017 >= 10000 THEN ''Big Spender''',
'            WHEN spend_2017 > spend_2016 AND (spend_2017 - spend_2016) > 1000 THEN ''Growth Potential''',
'            WHEN orders_2017 = 0 AND orders_2016 > 0 THEN ''Lapsed Customer''',
'            WHEN orders_2017 < orders_2016 AND spend_2017 < spend_2016 THEN ''Declining''',
'            ELSE ''Standard Customer''',
'        END AS customer_segment,',
'        CASE',
'            WHEN credit_limit - total_spend > 0 THEN credit_limit - total_spend',
'            ELSE 0',
'        END AS remaining_credit',
'    FROM',
'        customer_stats',
'),',
'rfm_analysis AS (',
'    SELECT',
'        customer_name,',
'        days_since_last_order AS recency,',
'        orders_2017 AS frequency,',
'        spend_2017 AS monetary,',
'        customer_segment,',
'        -- RFM scoring (1-5 scale)',
'        NTILE(5) OVER (ORDER BY days_since_last_order DESC) AS recency_score,',
'        NTILE(5) OVER (ORDER BY orders_2017) AS frequency_score,',
'        NTILE(5) OVER (ORDER BY spend_2017) AS monetary_score,',
'        -- Composite RFM score',
'        NTILE(5) OVER (ORDER BY days_since_last_order DESC) + ',
'        NTILE(5) OVER (ORDER BY orders_2017) + ',
'        NTILE(5) OVER (ORDER BY spend_2017) AS rfm_score',
'    FROM',
'        customer_segmentation',
'    WHERE',
'        orders_2017 > 0',
')',
'SELECT',
'    customer_name AS "Customer",',
'    recency AS "Days Since Last Order",',
'    frequency AS "2017 Orders",',
'    monetary AS "2017 Spend",',
'    customer_segment AS "Segment",',
'    recency_score AS "R Score",',
'    frequency_score AS "F Score",',
'    monetary_score AS "M Score",',
'    rfm_score AS "RFM Score",',
'    CASE',
'        WHEN rfm_score >= 13 THEN ''Champions''',
'        WHEN rfm_score >= 11 THEN ''Loyal''',
'        WHEN rfm_score >= 9 THEN ''Potential''',
'        WHEN rfm_score >= 7 THEN ''Needs Attention''',
'        ELSE ''At Risk''',
'    END AS "RFM Tier",',
'    ROUND(monetary / NULLIF(frequency, 0), 2) AS "Avg Order Value"',
'FROM',
'    rfm_analysis',
'ORDER BY',
'    rfm_score DESC, monetary DESC'))
,p_items_x_column_name=>'F Score'
,p_items_y_column_name=>'R Score'
,p_items_z_column_name=>'M Score'
,p_group_name_column_name=>'Segment'
,p_group_short_desc_column_name=>'Segment'
,p_items_label_column_name=>'Customer'
,p_items_short_desc_column_name=>'Customer'
,p_color=>'#b9b9f6'
,p_line_style=>'solid'
,p_marker_rendered=>'auto'
,p_marker_shape=>'auto'
,p_items_label_rendered=>false
);
