,p_plug_name=>'Inventory Turnover Analysis (2016-2017)'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH inventory_movements AS (',
'    SELECT',
'        p.product_id,',
'        p.product_name,',
'        pc.category_name,',
'        -- Beginning inventory (2016)',
'        NVL(SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2016 THEN oi.quantity ELSE 0 END), 0) AS sold_2016,',
'        -- Ending inventory (2017)',
'        NVL(SUM(CASE WHEN EXTRACT(YEAR FROM o.order_date) = 2017 THEN oi.quantity ELSE 0 END), 0) AS sold_2017,',
'        -- Average inventory calculation',
'        ROUND(NVL((SELECT AVG(quantity) FROM inventories WHERE product_id = p.product_id), 0),2) AS avg_inventory',
'    FROM',
'        products p',
'        JOIN product_categories pc ON p.category_id = pc.category_id',
'        LEFT JOIN order_items oi ON p.product_id = oi.product_id',
'        LEFT JOIN orders o ON oi.order_id = o.order_id AND o.status = ''Shipped''',
'    WHERE',
'        EXTRACT(YEAR FROM o.order_date) IN (2016, 2017)',
'    GROUP BY',
'        p.product_id, p.product_name, pc.category_name',
'),',
'turnover_calculation AS (',
'    SELECT',
'        product_id,',
'        product_name,',
'        category_name,',
'        sold_2016,',
'        sold_2017,',
'        avg_inventory,',
'        CASE ',
'            WHEN avg_inventory > 0 THEN ROUND(sold_2017 / avg_inventory, 2)',
'            ELSE 0 ',
'        END AS turnover_ratio_2017,',
'        RANK() OVER (ORDER BY CASE WHEN avg_inventory > 0 THEN ROUND(sold_2017 / avg_inventory, 2) ELSE 0 END DESC) AS turnover_rank',
'    FROM',
'        inventory_movements',
')',
'SELECT',
'    product_id,',
'    product_name,',
'    category_name,',
'    sold_2016,',
'    sold_2017,',
'    avg_inventory,',
'    turnover_ratio_2017,',
'    CASE',
'        WHEN turnover_ratio_2017 = 0 THEN ''No Turnover''',
'        WHEN turnover_ratio_2017 < 2 THEN ''Slow Moving''',
'        WHEN turnover_ratio_2017 < 5 THEN ''Normal''',
'        WHEN turnover_ratio_2017 < 10 THEN ''Fast Moving''',
'        ELSE ''Very Fast Moving''',
'    END AS turnover_category,',
'    turnover_rank',
'FROM',
'    turnover_calculation',
'ORDER BY',
'    turnover_ratio_2017 DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
