'SELECT',
'    turnover_category,',
'    COUNT(*) AS product_count,',
'    ROUND(COUNT(*) * 100 / SUM(COUNT(*)) OVER (), 1) AS percentage,',
'    -- Additional metrics for tooltips',
'    SUM(sold_2017) AS total_units_sold,',
'    ROUND(AVG(turnover_ratio_2017), 2) AS avg_turnover_ratio,',
'    ROUND(AVG(avg_inventory), 2) AS avg_inventory_level',
'FROM',
'    categorized_products',
'GROUP BY',
'    turnover_category',
'ORDER BY',
'    CASE turnover_category',
'        WHEN ''Very Fast Moving'' THEN 1',
'        WHEN ''Fast Moving'' THEN 2',
'        WHEN ''Normal'' THEN 3',
'        WHEN ''Slow Moving'' THEN 4',
'        ELSE 5',
'    END;'))
,p_items_value_column_name=>'PRODUCT_COUNT'
,p_items_label_column_name=>'TURNOVER_CATEGORY'
,p_items_label_rendered=>true
,p_items_label_position=>'auto'
,p_items_label_display_as=>'LABEL'
);
end;
